import React, { useEffect, useState } from 'react';
import './Login.css';

export default function Login({ onLogin, initialMessage = '' }) {
  const [role, setRole] = useState('owner');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState(initialMessage);
  const [busy, setBusy] = useState(false);
  useEffect(() => { setError(initialMessage || ''); }, [initialMessage]);

  async function submit(event) {
    event.preventDefault();
    setBusy(true);
    setError('');
    try {
      await onLogin(email, password, role);
    } catch (err) {
      const messages = {
        'auth/invalid-credential': 'Email ya password galat hai.',
        'auth/invalid-email': 'Valid email address daalein.',
        'auth/too-many-requests': 'Bahut attempts hue. Thodi der baad try karein.',
        'auth/network-request-failed': 'Internet connection check karein.',
        'auth/user-disabled': 'Yeh account disabled hai. Admin se contact karein.',
        'estateflow/role-mismatch': err.message,
      };
      setError(messages[err.code] || err.message || 'Login nahi ho saka. Firebase Auth settings check karein.');
    } finally { setBusy(false); }
  }

  return <div className="login-page"><div className="login-left"><div className="brand login-brand"><div className="brand-logo">E<span>+</span></div><div className="brand-text"><strong>estateflow<span>.</span></strong><small>CRM PLATFORM</small></div></div><div className="login-hero"><span className="pill light">REAL ESTATE, IN ONE FLOW</span><h1>Every lead has a story.<br/><em>Close the next chapter.</em></h1><p>A shared, Firebase-backed workspace for property teams — from first enquiry to final booking.</p><div className="hero-points"><span>✓ Live lead pipeline</span><span>✓ Company workspaces</span><span>✓ Team, visits & payroll</span></div></div><div className="login-decoration"><div className="orbit orbit-one"/><div className="orbit orbit-two"/><div className="float-card card-one"><span className="mini-icon purple">↗</span><div><small>Lead pipeline</small><b>Live updates</b></div></div><div className="float-card card-two"><span className="mini-icon green">✓</span><div><small>Company data</small><b>Cloud synced</b></div></div></div><div className="login-foot">Secure sign-in for platform administrators, company owners and employees.</div></div><div className="login-right"><form className="login-box" onSubmit={submit}><span className="eyebrow">WELCOME TO ESTATEFLOW</span><h2>Sign in to your workspace</h2><p>Select your login type, then enter the Firebase Authentication credentials assigned to you.</p><div className="role-cards" role="group" aria-label="Select login type"><button type="button" className={role==='superadmin'?'chosen':''} aria-pressed={role==='superadmin'} onClick={()=>{setRole('superadmin');setError('');}}><span>✦</span><b>My Login</b><small>Super Admin</small></button><button type="button" className={role==='owner'?'chosen':''} aria-pressed={role==='owner'} onClick={()=>{setRole('owner');setError('');}}><span>♙</span><b>Owner Login</b><small>Company workspace</small></button><button type="button" className={role==='employee'?'chosen':''} aria-pressed={role==='employee'} onClick={()=>{setRole('employee');setError('');}}><span>♧</span><b>Employee Login</b><small>Team workspace</small></button></div><label className="login-input-label">Email address<input required type="email" autoComplete="username" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@company.com"/></label><label className="login-input-label">Password<input required type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="Enter password"/></label>{error && <div className="login-warning"><span>ⓘ</span><p>{error}</p></div>}<button className="btn primary login-btn" disabled={busy}>{busy ? 'Signing in…' : `Sign in as ${role==='superadmin'?'Super Admin':role==='owner'?'Owner':'Employee'}`} <span>→</span></button><div className="login-warning"><span>ⓘ</span><p><b>Secure role-based access</b><br/>The selected tab must match your role stored in the Firestore <code>users</code> profile. Email and password must already be created in Firebase Authentication.</p></div></form></div></div>;
}
